from dataclasses import dataclass,field
import numpy as np
import struct, re, math, copy, os
from timbres import build

def pitch(obj):
    if not isinstance(obj,str): return int(obj)
    m=re.fullmatch(r'([A-G])([#b]?)(-?\d+)',obj.strip()); assert m,obj
    a,b,c=m.groups()
    return 12*(int(c)+1)+{'C':0,'D':2,'E':4,'F':5,'G':7,'A':9,'B':11}[a]+{'':0,'b':-1,'#':1}[b]
@dataclass
class Event:
    row:int; key:int; inst:int; vel:float; dur:object=None; pan:object=None
    fx:object=None; vib:object=None; glide:tuple=(); mods:tuple=(); release:float=0
    text:str=''

class Track:
    def __init__(self,bars=44,bpm=142,channels=16):
        assert bars%4==0 and channels%2==0
        self.bars=bars; self.nrows=16*bars; self.bpm=bpm; self.ch=channels
        self.ev=[[] for _ in range(channels)]; self.instr=build()
        self.groove=[(6 if 16<=r//16<20 else (7 if not r%2 else 5)) for r in range(self.nrows)]
        self.gain={}; self.warnings=[]
    def put(self,ch,b,r,k,i,v,d=None,pan=None,fx=None,vib=None,glide=(),mods=(),rel=0):
        """b,r = bar and sixteenth; d in swung sixteenths. fx, vib, slides are XM commands."""
        row=b*16+r
        assert int(row)==row
        if row>=self.nrows:return
        self.ev[ch].append(Event(int(row),pitch(k),i,v,d,pan,fx,vib,tuple(glide),tuple(mods),rel))
    def to_cells(self,mute=()):
        C=[[[0,0,0,0,0] for ch in range(self.ch)] for r in range(self.nrows)]
        for row,g in enumerate(self.groove):
            if row==0 or self.groove[row-1]!=g:
                C[row][-1][3:]=[15,g]
        self.warnings=[]
        for ch in range(self.ch):
            if ch in mute:continue
            order=sorted(self.ev[ch],key=lambda e:e.row)
            for j,e in enumerate(order):
                s=e.row
                next_s=order[j+1].row if j+1<len(order) else self.nrows
                if next_s==s:
                    self.warnings.append('two attacks: ch%d row%d (%s, %s)'%(ch,s,e,order[j+1]));continue
                cell=C[s][ch]
                vol=max(0,min(64,round(e.vel*self.gain.get(e.inst,1))))
                cell[:3]=[e.key-11,e.inst,0x10+vol]
                assert 1<=cell[0]<=96, (s,ch,e)
                if e.fx is not None: cell[3:]=e.fx
                elif e.pan is not None and e.pan!=self.instr[e.inst].pan: cell[3:]=[8,max(0,min(255,round(e.pan)))]
                end=float(next_s if e.dur is None else min(s+e.dur,next_s))
                m=math.ceil(end-1e-8)
                # Delayed vibrato manually set on the longer notes. (offset, speed+depth)
                if e.vib:
                    off,val=e.vib
                    if s+off<m:
                        for r in range(s+off,m): C[r][ch][3:]=[4, val if r==s+off else 0]
                # Curves also work in ports that don't support instrument envelopes.
                lastkey=e.key
                for off,key,rate in e.glide:
                    key=pitch(key)
                    r=s+off
                    if r>=m:break
                    vcell=C[r][ch]; vcell[0]=key-11; vcell[3:]=[3,rate]
                    n=abs(key-lastkey)*16-(self.groove[r]-1)*rate
                    while n>0 and r+1<m:
                        r+=1;C[r][ch][3:]=[3,rate];n-=(self.groove[r]-1)*rate
                    lastkey=key
                for off,fx,par in e.mods:
                    if s+off<m:C[s+off][ch][3:]=[fx,par]
                E=math.floor(end+1e-6); fraction=end-E
                if e.dur is None:continue
                cut=(end<next_s-.00001)
                if e.release and end-s>=1.6:
                    # taper the last row instead of stretching everything to the grid
                    use=(fraction>=.51 and E<next_s)
                    row=E if use else E-1
                    if row>s and row<next_s:
                        ticks=max(1,round(self.groove[row]*fraction)-1) if use else self.groove[row]-1
                        q=max(1,min(15,round(vol*e.release/ticks)))
                        C[row][ch][2]=0x60+q
                if cut:
                    if fraction<.08:
                        if E<self.nrows:C[E][ch][0]=97
                    else:
                        tick=round(fraction*self.groove[E]);tick=max(1,min(self.groove[E]-1,tick))
                        C[E][ch][3:]=[14,0xC0+tick]
        return C
    def save(self,path,title='Latchkey Aurora',mute=(),limit_pats=None):
        C=self.to_cells(mute)
        N=self.bars//4 if limit_pats is None else limit_pats
        def s(x,n): return x.encode('ascii','replace')[:n].ljust(n,b'\0')
        with open(path,'wb') as f:
            f.write(b'Extended Module: '+s(title,20)+b'\x1a'+s('FastTracker v2.00',20)+b'\x04\x01')
            f.write(struct.pack('<I8H',276,N,0,self.ch,N,len(self.instr)-1,1,6,self.bpm))
            f.write(bytes(range(N)).ljust(256,b'\x00'))
            for pat in range(N):
                data=bytearray()
                for row in C[pat*64:pat*64+64]:
                    for c in row:
                        mask=sum(1<<k for k,num in enumerate(c) if num)
                        if mask==31:data.extend(c)
                        else:
                            data.append(0x80|mask);data.extend(v for v in c if v)
                f.write(struct.pack('<IBHH',9,0,64,len(data))+data)
            for ins in self.instr[1:]:
                f.write(struct.pack('<I22sBHI',263,s(ins.name,22),0,1,40)+bytes(230))
                pcm=ins.pcm; lstart,llen=ins.loop
                typ=16+bool(llen)
                f.write(struct.pack('<3IBbBBbB22s',len(pcm)*2,lstart*2,llen*2,ins.volume,0,typ,ins.pan,ins.rel,0,s(ins.label,22)))
                raw=np.diff(pcm.astype('int32'),prepend=0).astype('<i2');f.write(raw.tobytes())
        return C
if __name__=='__main__':
