    for b in range(4):
        t.put(10,b,0,'F#5',13,41,5.6,vib=(3,0x43),rel=.5)
        t.put(10,b,7,'D5',13,40,2.7);t.put(10,b,11,'B4',13,38,4.3,glide=[(2,'C#5',10)])
        for r in [0,7,10]:t.put(0,b,r,'C4',1,50)
        for r in [4,12]:t.put(1,b,r,'C4',2,49)
        for r in range(0,16,2):t.put(2,b,r,'C4',3,25)
    t.save('../test.xm')
