import numpy as np, wave, sys, os

def read(path):
    w=wave.open(path); a=np.frombuffer(w.readframes(w.getnframes()),'<i2').reshape(-1, w.getnchannels()); return w.getframerate(),a.astype(np.float64)/32768

def db(x):return 20*np.log10(np.maximum(x,1e-12))
def rms(x):return np.mean(x*x)**.5

def bands(x,rate,n=4096):
    y=x[:len(x)//n*n].reshape(-1,n,2)*np.hanning(n)[None,:,None]
    spec=np.mean(abs(np.fft.rfft(y,axis=1))**2,axis=(0,2)); freqs=np.fft.rfftfreq(n,1/rate)
    ret=[]
    for low,hi in zip([0,35,75,140,300,650,1300,2800,5500,10000],[35,75,140,300,650,1300,2800,5500,10000,rate/2+.1]):
        ret.append(spec[(freqs>=low)&(freqs<hi)].sum()/spec.sum())
    return np.round(100*np.array(ret),2)

def audit(path):
    rate,x=read(path); dur=len(x)/rate; bar=240/142
    print('rate',rate,'duration',round(dur,4),'bar',bar, 'means',x.mean(axis=0))
    print('rms peak dB',tuple(np.round(db(a),2) for a in (rms(x),max(abs(x).max(axis=0)))),'clip counts',np.sum(abs(x)>=.99996),'sample',x.shape)
    print('RMS channels',db(np.mean(x*x,axis=0)**.5),'corr',np.corrcoef(x.T)[0,1], 'side/mid dB',db(rms(x[:,0]-x[:,1])/rms(x.sum(axis=1))))
    print('band fractions %',bands(x,rate))
    print('bar    rms   peak   rmsLo Hi(window 50ms)  crest   LRcorr  band%       sub  bass  body   middle    hi       air')
    for b in range(44):
        xx=x[int(b*bar*rate):int((b+1)*bar*rate)];l=len(xx)//32
        env=np.sqrt(np.mean(xx[:l*32].reshape(32,l,2)**2,axis=(1,2)))
        print('%2d  %6.2f %6.2f  %6.2f %6.2f     %4.1f    %5.3f '%(b,db(rms(xx)),db(np.max(abs(xx))),db(np.min(env)),db(np.max(env)),db(np.max(abs(xx))/rms(xx)),np.corrcoef(xx.T)[0,1]),' '.join('%4.1f'%v for v in bands(xx,rate)))
    print('first nonzero',np.where(np.max(np.abs(x),axis=1)>1e-4)[0][0],'last >.001',len(x)-np.where(np.max(np.abs(x),axis=1)>.001)[0][-1], 'end peak',np.max(abs(x[-200:])))
if __name__=='__main__':audit(sys.argv[1])
